(function(){var b=document.querySelector('#nsa .mtog'),n=document.getElementById('mainnav');if(!b||!n)return;function set(o){b.setAttribute('aria-expanded',o?'true':'false');b.setAttribute('aria-label',o?'Close menu':'Open menu');n.classList.toggle('open',o);}b.addEventListener('click',function(){set(b.getAttribute('aria-expanded')!=='true')});n.addEventListener('click',function(e){if(e.target.closest('a'))set(false)});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&n.classList.contains('open')){set(false);b.focus();}});window.addEventListener('resize',function(){if(window.innerWidth>960)set(false)});})();
